 function saveForm(form){if(!window.AWBBridge.editable()){render();return;}
  if(form.id==='v8-reminder-form'){
   const text=String(new FormData(form).get('text')||'').trim();if(!text){toast('请填写提醒内容');return;}
   undoState=snapshot();const r=reminders.find(r=>r.id===form.dataset.id);
   if(r)r.text=text;else reminders.push({id:'reminder-'+crypto.randomUUID(),text,date:todayISO(),done:false});
   render();closeDialog();toast('提醒已保存',true);return;
  }
  if(form.id==='kf-task-form'){
   const f=new FormData(form),title=String(f.get('title')).trim();if(!title){toast('请填写任务标题');form.elements.title.focus();return;}
   const link=String(f.get('link')||'').trim();if(link&&!/^https?:\/\//i.test(link)){toast('资料链接需填写 http:// 或 https:// 地址');return;}
   undoState=snapshot();const existing=tasks.find(t=>t.id===form.dataset.id),target=String(f.get('lane')),oldStatus=existing?.status;
   const t=existing||{id:'task-'+crypto.randomUUID(),type:'行动',follow:'',waiting:'待补',createdOrder:Date.now(),boardOrder:Date.now(),checked:false,fact:'手动创建。'};
   for(const key of ['title','source','description','priority','owner','due','project','follow','next','waiting','link'])t[key]=String(f.get(key)||'').trim();
   t.owner=t.owner||'待补';t.source=t.source||'手动添加';t.next=t.next||t.description||t.title;
   if(!existing||laneOf(t)!==target){const restore=oldStatus==='done'&&target==='doing'&&t.returnStatus==='wait';if(target==='done'){t.returnStatus=oldStatus&&oldStatus!=='done'?oldStatus:'todo';t.checked=true;}else if(oldStatus==='done')t.checked=false;t.status=restore?'wait':target;t.boardOrder=Date.now();}
   if(target==='doing')t.status=f.get('waitingFlag')==='yes'?'wait':'doing';
   if(!existing)tasks.push(t);
   const reveal=!existing||filter!=='all'||search||project!=='all'&&project!==t.project;
   if(reveal){filter='all';search='';q('#pw-search').value='';if(project!=='all'&&project!==t.project)project='all';}
   render();closeDialog();revealFollowup(t.id);toast(existing?'任务已更新':'已创建任务 · '+laneName(target),true);return;
  }
  if(form.id==='pw-edit-form'){
   const t=tasks.find(x=>x.id===form.dataset.editId),f=new FormData(form),target=String(f.get('status'));undoState=snapshot();
   if(t.status!==target){t.boardOrder=Date.now();if(target==='done'){t.returnStatus=t.status;t.checked=true;}else if(t.status==='done')t.checked=false;}
   for(const key of ['status','owner','due','follow','next','waiting','link'])t[key]=String(f.get(key)).trim();t.description=t.next;render();closeDialog();toast('事项已更新',true);
  }
  if(form.id==='pw-convert-form'){
   const f=new FormData(form),i=Number(form.dataset.index),r=raws[i];undoState=snapshot();tasks.push({id:'task-'+crypto.randomUUID(),title:String(f.get('title')).trim(),project:String(f.get('project')),next:String(f.get('next')).trim(),description:String(f.get('next')).trim(),source:'需求收集',priority:'unset',checked:false,status:'todo',boardOrder:Date.now(),type:'需明确',due:'',follow:'',owner:'待补',waiting:'待补',fact:r.text});raws.splice(i,1);render();closeDialog();toast('已加入需求接收 · 原始记录随事项保留',true);
  }
 }
