 // Dates are evaluated in the user's work timezone, including saved copies.
 function todayISO(){return new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Shanghai',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date());}
 function reminderEntries(taskList,manual,today){
  const entries=taskList.filter(t=>!isChecked(t)).map(t=>{
   const flags=[];
   if(t.due&&t.due<=today)flags.push(t.due<today?'已逾期':'今天到期');
   if(t.follow&&t.follow<=today)flags.push(t.follow<today?'跟进已到期':'今天跟进');
   if(!flags.length)return null;
   return {kind:'task',id:t.id,text:t.title,project:t.project,label:flags.join(' · '),overdue:!!((t.due&&t.due<today)||(t.follow&&t.follow<today)),date:[t.due,t.follow].filter(d=>d&&d<=today).sort()[0],done:false};
  }).filter(Boolean);
  for(const r of manual.filter(r=>r.date===today||r.date<today&&!r.done))entries.push({kind:'manual',...r,label:r.date<today?'此前未完成':'今日重点',overdue:r.date<today&&!r.done});
  return entries.sort((a,b)=>Number(a.done)-Number(b.done)||Number(b.overdue)-Number(a.overdue)||a.date.localeCompare(b.date));
 }
 function renderReminders(){
  const today=todayISO(),entries=reminderEntries(base(),reminders,today);
  q('#v8-today-label').textContent=today.slice(5).replace('-','月')+'日';
  q('#v8-reminder-count').textContent=entries.filter(r=>!r.done).length;
  q('#v8-reminder-list').innerHTML=entries.map(r=>'<article class="v8-reminder-row" data-done="'+!!r.done+'">'+(r.kind==='manual'?'<input class="v8-reminder-check" type="checkbox" data-reminder-check="'+esc(r.id)+'" aria-label="完成提醒：'+esc(r.text)+'"'+(r.done?' checked':'')+'>':'')+'<div class="v8-reminder-body"><div class="v8-reminder-meta"><span class="v8-reminder-tag'+(r.overdue?' overdue':'')+'">'+esc(r.label)+'</span><span>'+esc(r.project||'手动提醒')+(r.overdue?' · '+date(r.date):'')+'</span></div><button type="button" class="v8-reminder-title" '+(r.kind==='task'?'data-kf-edit':'data-reminder-edit')+'="'+esc(r.id)+'">'+esc(r.text)+'</button></div>'+(r.kind==='manual'?'<button type="button" class="v8-reminder-delete" data-reminder-delete="'+esc(r.id)+'" aria-label="删除提醒：'+esc(r.text)+'">×</button>':'')+'</article>').join('')||'<div class="v8-reminder-empty">今天暂无到期或需跟进的事项<small>点击右上角“＋ 添加”，记下今天的重点。</small></div>';
 }
