 // Size all three overview lanes from their actual scroll viewport: seven rows.
 function fitOverviewRows(){
  const host=q('#kf-overview');
  if(view!=='overview'||kfDensity!=='dense'||root.getBoundingClientRect().width<=900)return;
  const scroller=host.querySelector('.kf-scroll');if(!scroller||!scroller.clientHeight)return;
  const style=getComputedStyle(scroller),gap=parseFloat(style.rowGap)||4;
  const available=scroller.clientHeight-(parseFloat(style.paddingTop)||0)-(parseFloat(style.paddingBottom)||0)-6*gap;
  const height=Math.max(48,Math.floor(available/7*100)/100)+'px';
  if(host.style.getPropertyValue('--v8-card-height')!==height)host.style.setProperty('--v8-card-height',height);
 }
 let v8FitFrame=0;
 function scheduleOverviewFit(){cancelAnimationFrame(v8FitFrame);v8FitFrame=requestAnimationFrame(fitOverviewRows);}
 const v8SizeObserver=typeof ResizeObserver==='function'?new ResizeObserver(scheduleOverviewFit):null;
