 const ixElements=(doc,name)=>[...doc.getElementsByTagNameNS('*',name)];
 function ixXml(s){const xml=new DOMParser().parseFromString(s,'application/xml');if(ixElements(xml,'parsererror').length)throw Error('文件结构无法识别，请重新另存为 .xlsx。');return xml;}
 function ixText(el,name){return ixElements(el,name)[0]?.textContent||'';}
 async function ixReadFile(file){
  if(!/\.xlsx$/i.test(file.name))throw Error('请选择 .xlsx 文件；旧版 .xls 请先另存为 .xlsx。');
  if(file.size>5*1024*1024)throw Error('文件超过 5 MB，请仅保留需要导入的任务后再试。');
  const zip=await JSZip.loadAsync(await file.arrayBuffer());
  if(Object.keys(zip.files).length>300)throw Error('文件包含过多内容，请使用提供的任务模板。');
  if(zip.file('xl/vbaProject.bin'))throw Error('请使用不含宏的 .xlsx 任务模板。');
  const read=async(path,required=true)=>{const f=zip.file(path);if(!f){if(required)throw Error('缺少 Excel 数据，请使用下载的任务模板。');return null;}const s=await f.async('string');if(s.length>4000000)throw Error('任务数据过大，请拆分后导入。');return ixXml(s);};
  const book=await read('xl/workbook.xml'),rels=await read('xl/_rels/workbook.xml.rels');
  const sheet=ixElements(book,'sheet').find(s=>s.getAttribute('name')==='任务数据');if(!sheet)throw Error('没有找到“任务数据”工作表。请保留模板中的工作表名称。');
  const rid=sheet.getAttribute('r:id')||sheet.getAttributeNS('http://schemas.openxmlformats.org/officeDocument/2006/relationships','id');
  const relation=ixElements(rels,'Relationship').find(r=>r.getAttribute('Id')===rid);
  const target=relation?.getAttribute('Target');if(!target||relation.getAttribute('TargetMode')==='External')throw Error('任务数据的工作表关系无效。');
  const path=new URL(target,'https://xlsx.invalid/xl/workbook.xml').pathname.slice(1);
  const xml=await read(path),strings=await read('xl/sharedStrings.xml',false);
  if(ixElements(xml,'mergeCell').length)throw Error('任务数据中存在合并单元格。请取消合并，保持一行一件事。');
  const shared=strings?ixElements(strings,'si').map(si=>ixElements(si,'t').map(t=>t.textContent).join('')):[];
  const date1904=['1','true'].includes(ixElements(book,'workbookPr')[0]?.getAttribute('date1904'));
  const dataRows=[];
  for(const row of ixElements(xml,'row')){
   const values=[],formulas=[];
   for(const c of ixElements(row,'c')){
    const ref=c.getAttribute('r')||'',letters=ref.match(/^[A-Z]+/i)?.[0];if(!letters)continue;
    let col=0;for(const letter of letters.toUpperCase())col=col*26+letter.charCodeAt(0)-64;col--;
    if(col>99)continue;
    const type=c.getAttribute('t'),v=ixText(c,'v');
    if(ixElements(c,'f').length)formulas.push(col);
    values[col]=type==='s'?(shared[Number(v)]??''):type==='inlineStr'?ixElements(c,'t').map(t=>t.textContent).join(''):type==='b'?(v==='1'?'是':'否'):type==='e'?'#Excel错误':type==='n'||!type?(v===''?'':Number(v)):v;
   }
   if(values.some(v=>v!==undefined&&v!==''))dataRows.push({row:Number(row.getAttribute('r')),values,formulas});
  }
  const head=dataRows.find(r=>r.row===1);if(!head)throw Error('第一行缺少表头。请使用模板，保留第一行字段名称。');
  const clean=head.values.map(v=>String(v??'').trim()),known=clean.filter(x=>ixHeaders.includes(x));
  if(known.length!==new Set(known).size)throw Error('表头含重复字段，请确保每个字段只出现一次。');
  if(!clean.includes('任务标题'))throw Error('缺少“任务标题”列，请检查第一行表头。');
  const rows=dataRows.filter(r=>r.row>1).map(r=>{const raw={};const errors=[];clean.forEach((h,i)=>{if(ixHeaders.includes(h)){raw[h]=r.values[i]??'';if(r.formulas.includes(i))errors.push(h+'不能使用公式，请粘贴为值。');}});return {row:r.row,raw,errors};}).filter(r=>Object.values(r.raw).some(v=>String(v).trim()!==''));
  if(!rows.length)throw Error('任务数据目前是空白的。请从第二行填写任务；填写示例不会自动导入。');
  if(rows.length>1000)throw Error('一次最多导入 1,000 条任务，请拆分后再试。');
  return {rows,date1904};
 }
 function ixParseDate(v,date1904){
  if(v==='')return '';
  if(typeof v==='number'){
   if(!Number.isFinite(v)||v<1||v>2958465)throw Error('日期无效');
   const n=Math.floor(v);if(!date1904&&n===60)throw Error('日期无效');
   const epoch=date1904?Date.UTC(1904,0,1):Date.UTC(1899,11,31);
   return new Date(epoch+(n-(!date1904&&n>60?1:0))*86400000).toISOString().slice(0,10);
  }
  const s=String(v).trim(),m=s.match(/^(\d{4})[-/](\d{1,2})[-/](\d{1,2})(?:T00:00:00(?:\.000)?Z?)?$/);if(!m)throw Error('请填完整日期，如 2026-10-12，或留空');
  const y=Number(m[1]),mo=Number(m[2]),d=Number(m[3]),x=new Date(Date.UTC(y,mo-1,d));
  if(y<1900||y>9999||x.getUTCFullYear()!==y||x.getUTCMonth()!==mo-1||x.getUTCDate()!==d)throw Error('日期不存在');
  return `${m[1]}-${String(mo).padStart(2,'0')}-${String(d).padStart(2,'0')}`;
 }
 function ixTaskValues(t){return {id:t.id,title:t.title,project:t.project,lane:laneOf(t),checked:isChecked(t),priority:t.priority||'unset',owner:t.owner||'',due:t.due||'',next:t.next||'',pending:t.status==='wait',waiting:t.waiting||'',follow:t.follow||'',source:t.source||'',description:t.description||'',link:t.link||''};}
 function ixPrepare(input,name){
  const preview={name,rows:[],base:JSON.stringify(tasks)},ids=new Set(),blankKeys=new Set(),idMap=new Map(tasks.map(t=>[t.id,t]));
  for(const r of input.rows){
   const errors=[...(r.errors||[])],warn=[],raw=r.raw,str=h=>String(raw[h]??'').trim(),id=str('任务编号'),title=str('任务标题'),line=str('所属工作线');
   if(!title||title==='[清空]')errors.push('任务标题必填，不能使用 [清空]。');if(title.length>100)errors.push('标题不能超过 100 字。');if(id&&!/^[A-Za-z0-9_-]{1,80}$/.test(id))errors.push('任务编号只能用英文字母、数字、短横线或下划线，最多 80 字符。');
   if(id&&ids.has(id))errors.push('文件内任务编号重复：'+id);if(id)ids.add(id);
   const key=(line||'未分类')+'\u0000'+title;
   if(!id&&blankKeys.has(key))errors.push('文件内出现相同工作线、相同标题的无编号任务。');if(!id)blankKeys.add(key);
   let existing=id?idMap.get(id):null,matchByTitle=false;
   if(!id){const matches=tasks.filter(t=>t.title.trim()===title&&t.project===(line||'未分类'));if(matches.length===1){existing=matches[0];matchByTitle=true;}else if(matches.length>1)errors.push('同名任务不止一条，请填写任务编号。');}
   const old=existing?ixTaskValues(existing):null;
   const base=old||{id:'',title:'',project:'未分类',lane:'todo',checked:false,priority:'unset',owner:'待补',due:'',next:'',pending:false,waiting:'',follow:'',source:'Excel 导入',description:'',link:''};
   const next={...base,id:existing?.id||id||'IMP-'+crypto.randomUUID(),title};
   const textFields=[['所属工作线','project',80],['智能体/负责人','owner',80],['下一步','next',160],['等谁/等什么','waiting',200],['来源','source',80],['详细说明','description',1200],['资料链接','link',500]];
   for(const [h,k,max] of textFields){let v=str(h);if(!v)continue;if(v==='[清空]'){if(k==='project')errors.push('所属工作线不能清空，请填“未分类”。');else next[k]='';}else{next[k]=v;if(v.length>max)errors.push(h+'不能超过 '+max+' 字。');}}
   const laneVal=str('看板列'),checkedVal=str('是否完成'),pendingVal=str('待确认'),priorityVal=str('优先级');
   if(laneVal){const k=Object.keys(ixLaneNames).find(k=>ixLaneNames[k]===laneVal);if(k)next.lane=k;else errors.push('看板列只能是需求接收、推进中、已完成。');}
   if(priorityVal){const k=Object.keys(priorityName).find(k=>priorityName[k]===priorityVal);if(k)next.priority=k;else errors.push('优先级只能是未设置、高、中、低。');}
   for(const [h,v,k] of [['是否完成',checkedVal,'checked'],['待确认',pendingVal,'pending']])if(v){if(!['是','否'].includes(v))errors.push(h+'只能是“是”或“否”。');else next[k]=v==='是';}
   for(const [h,k] of [['截止日期','due'],['下次跟进日期','follow']]){const v=raw[h];if(v===undefined||String(v).trim()==='')continue;if(String(v).trim()==='[清空]'){next[k]='';continue;}try{next[k]=ixParseDate(v,input.date1904);}catch(e){errors.push(h+'：'+e.message);}}
   if(old?.lane==='done'&&next.lane!=='done'&&!checkedVal)next.checked=false;
   if(next.lane==='done'){if(checkedVal==='否')warn.push('已完成列将自动标记完成。');next.checked=true;}
   if(next.lane!=='doing'&&!pendingVal)next.pending=false;
   if(next.pending&&(next.lane!=='doing'||next.checked))errors.push('待确认=是时，须处于推进中且尚未完成。');
   if(next.pending&&!next.follow)warn.push('建议补充下次跟进日期。');
   if(next.link){try{const u=new URL(next.link);if(!['http:','https:'].includes(u.protocol))throw Error();}catch{errors.push('资料链接需填写完整 http:// 或 https:// 地址。');}}
   const changes=ixKeys.filter(k=>k!=='id'&&old&&old[k]!==next[k]).map(k=>({field:ixHeaders[ixKeys.indexOf(k)],from:old[k],to:next[k]}));
   if(matchByTitle&&changes.length)errors.push('发现同工作线的同名任务，内容有变化；请填写任务编号 '+existing.id+' 后更新。');
   let action=errors.length?'错误':existing?(changes.length?'更新':'跳过'):'新增';
   preview.rows.push({row:r.row,task:next,existing:existing?.id,action,errors,warn,changes});
  }
  return preview;
 }
 function ixDisplay(v,field){if(field==='看板列')return ixLaneNames[v]||v;if(field==='优先级')return priorityName[v]||v;if(typeof v==='boolean')return v?'是':'否';return v||'空白';}
 function ixShowPreview(){
  const p=ixPreview,c=a=>p.rows.filter(r=>r.action===a).length,problems=c('错误'),writes=c('新增')+c('更新');
  ixDialog('检查导入预览',ixSteps(2)+'<p class="ix-lead">'+esc(p.name)+' · “任务数据” '+p.rows.length+' 条 · 尚未修改看板</p><div class="ix-summary">'+['新增','更新','跳过','错误'].map(a=>'<span class="ix-chip '+(a==='错误'&&problems?'error':'')+'">'+a+' <b>'+c(a)+'</b></span>').join('')+'</div>'+(problems?'<div class="ix-error" role="alert">请先修正 '+problems+' 条错误，再重新上传。当前整批不会写入。</div>':'')+'<div class="ix-table-wrap"><table class="ix-table"><colgroup><col style="width:7%"><col style="width:9%"><col style="width:29%"><col style="width:13%"><col style="width:42%"></colgroup><thead><tr><th>行号</th><th>处理</th><th>任务</th><th>所在列</th><th>变更 / 检查结果</th></tr></thead><tbody>'+p.rows.map(r=>'<tr><td>'+r.row+'</td><td>'+r.action+'</td><td>'+esc(r.task.title||'未填标题')+'<small>'+esc(r.task.project)+'</small><small class="ix-id">'+esc(r.task.id)+'</small></td><td>'+ixLaneNames[r.task.lane]+(r.task.checked?'<small>已勾选完成</small>':'')+'</td><td>'+(r.errors.length?r.errors.map(x=>'<div class="ix-warning" style="color:#b04b53">'+esc(x)+'</div>').join(''):r.action==='跳过'?'与已有任务相同':r.changes.length?'<details class="ix-diff"><summary>'+r.changes.length+' 个字段变化，查看明细</summary>'+r.changes.map(x=>'<div>'+esc(x.field)+'：'+esc(ixDisplay(x.from,x.field))+' → '+esc(ixDisplay(x.to,x.field))+'</div>').join('')+'</details>':'新增至'+ixLaneNames[r.task.lane])+(r.warn.length?'<div class="ix-warning">'+r.warn.map(esc).join('<br>')+'</div>':'')+'</td></tr>').join('')+'</tbody></table></div><p class="ix-muted" style="margin-top:10px">按编号新增或更新；空白字段保留原值。未列出的旧任务不会删除。</p><div class="ix-actions"><button type="button" class="pw-btn" data-ix-back>重新选择文件</button><button type="button" class="pw-btn pw-primary" data-ix-confirm '+(problems||!writes?'disabled':'')+'>确认导入 '+writes+' 条</button></div>');
 }
 function ixCommit(){if(!window.AWBBridge.editable()){render();return;}
  if(!ixPreview||ixPreview.rows.some(r=>r.errors.length))return;
  if(JSON.stringify(tasks)!==ixPreview.base){toast('看板已发生变化，请重新上传，生成最新预览。');return;}
  const todo=ixPreview.rows.filter(r=>['新增','更新'].includes(r.action));if(!todo.length)return;
  undoState=snapshot();
  for(const r of todo){const v=r.task,existing=tasks.find(t=>t.id===r.existing),t=existing||{id:v.id,type:'行动',createdOrder:Date.now(),boardOrder:Date.now(),fact:'从 Excel 导入：'+ixPreview.name+'，任务数据第 '+r.row+' 行。'};const oldStatus=t.status;for(const k of ['id','title','project','priority','owner','due','next','waiting','follow','source','description','link','checked'])t[k]=v[k];t.status=v.lane==='doing'&&v.pending?'wait':v.lane;if(v.lane==='done')t.returnStatus=oldStatus&&oldStatus!=='done'?oldStatus:'doing';t.importedFrom=ixPreview.name;t.importedRow=r.row;if(!existing)tasks.push(t);}
  const n=todo.filter(r=>r.action==='新增').length,u=todo.length-n;
  ixPreview=null;ixToken++;project='all';filter='all';search='';q('#pw-search').value='';switchView('table');closeDialog();toast('已导入：新增 '+n+' 条，更新 '+u+' 条',true);
 }
 async function ixUpload(file){
  if(!file)return;const token=++ixToken;
  q('#ix-upload-message').innerHTML='<p class="ix-muted" style="margin-top:12px">正在读取和校验…</p>';
  try{const input=await ixReadFile(file);if(token!==ixToken||q('#pw-overlay').hidden)return;ixPreview=ixPrepare(input,file.name);ixShowPreview();}
  catch(e){if(token!==ixToken||q('#pw-overlay').hidden)return;const box=q('#ix-upload-message');if(box)box.innerHTML='<div class="ix-error" role="alert">'+esc(e.message||'文件无法读取，请重新另存为 .xlsx。')+'</div>';}
 }
 function ixDemo(){
  const raw=(title,lane,done,pending)=>Object.fromEntries(ixHeaders.map(h=>[h,({'任务标题':title,'所属工作线':'导入体验','看板列':lane,'是否完成':done,'待确认':pending,'优先级':'中','下一步':'这是填写演示，可撤销本次导入。','来源':'导入体验示例'})[h]||'']));
  ixPreview=ixPrepare({date1904:false,rows:[{row:2,raw:raw('示例：整理规划输入','需求接收','否','否')},{row:3,raw:raw('示例：等待方案反馈','推进中','否','是')},{row:4,raw:raw('示例：完成会议摘要','推进中','是','否')}]},'导入流程体验（示例）');ixShowPreview();
 }
 root.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.id==='ix-open'||b.hasAttribute('data-ix-back'))ixOpen();if(b.hasAttribute('data-ix-download'))ixDownload();if(b.hasAttribute('data-ix-demo'))ixDemo();if(b.hasAttribute('data-ix-confirm'))ixCommit();});
 root.addEventListener('change',e=>{if(e.target.id==='ix-file')ixUpload(e.target.files[0]);});

